def _business_projection(
    events: Any, expected: Mapping[str, Mapping[str, Any]]
) -> list[dict[str, Any]]:
    projection: list[dict[str, Any]] = []
    seen: set[str] = set()
    for event in events if isinstance(events, list) else []:
        if not isinstance(event, Mapping):
            continue
        event_type = str(event.get("type") or "")
        if not _is_business_event(event_type):
            continue
        payload = _event_payload(event)
        label = next((name for name, wanted in expected.items() if payload == wanted), None)
        if label is None:
            label = f"unexpected:{event_type}:{event.get('seq')}"
        elif label in _REPEATABLE_LABELS and label in seen:
            continue
        seen.add(label)
        projection.append({"label": label, "seq": event.get("seq"), "payload": payload})
    return projection


def _note_predicate(raw: Mapping[str, Any], group_name: str) -> tuple[bool, Any, Any, str | None]:
    groups = raw.get("groups") if isinstance(raw.get("groups"), Mapping) else {}
    actual = groups.get(group_name) if isinstance(groups.get(group_name), Mapping) else {}
    expected_note = dict(_NOTE_EXPECTED[group_name])
    expected_note["cover"] = {**expected_note["cover"], "valid_data_url": True}
    observed_note = actual.get("note") if isinstance(actual.get("note"), Mapping) else {}
    note_projection = {key: observed_note.get(key) for key in expected_note}
    expected = {
        "match_count": 1,
        "note": expected_note,
        "application_build": EXPECTED_BUILD,
    }
    projected = {
        "match_count": actual.get("match_count"),
        "note": note_projection,
        "application_build": actual.get("application_build"),
    }
    passed = projected == expected and isinstance(observed_note.get("id"), str) and bool(observed_note.get("id"))
    return passed, expected, actual, _failure(projected, expected, extra=not passed)


